			'payment_method'    => array(
				$payment_method_ids[ $i % count( $payment_method_ids ) ],
				$payment_method_ids[ ( $i + 1 ) % count( $payment_method_ids ) ],
				$payment_method_ids[ ( $i + 2 ) % count( $payment_method_ids ) ],
