			'country' => array( $country_list[ $i % count( $country_list ) ][ $lang ], $country_list[ ( $i + 1 ) % count( $country_list ) ][ $lang ] ),
		);

		$per_lang[ $lang ] = array(
			'args' => array(
				'post_type'    => 'casino',
				'post_title'   => $c['name'],
				'post_content' => '<p>' . nl2br( esc_html( $c['content'][ $lang ] ) ) . '</p>',
				'post_status'  => 'publish',
				'post_name'    => sanitize_title( $c['name'] ) . ( 'en' === $lang ? '' : '-' . $lang ),
