	array( 'cat' => 'Beginner Guides',
		'title' => array( 'en' => 'RTP Explained: How Return to Player Actually Works', 'de' => 'RTP erklärt: Wie der Auszahlungsprozentsatz wirklich funktioniert', 'zh' => 'RTP详解：返还率究竟如何运作', 'es' => 'RTP Explicado: Cómo Funciona Realmente el Retorno al Jugador', 'pt' => 'RTP Explicado: Como Funciona Realmente o Retorno ao Jogador', 'fr' => 'Le RTP Expliqué : Comment Fonctionne Réellement le Taux de Retour au Joueur', 'it' => 'RTP Spiegato: Come Funziona Davvero il Ritorno al Giocatore', 'sv' => 'RTP Förklarat: Hur Återbetalning till Spelaren Faktiskt Fungerar', 'nb' => 'RTP Forklart: Hvordan Tilbakebetaling til Spilleren Egentlig Fungerer', 'fi' => 'RTP Selitettynä: Miten Pelaajalle Palautuminen Todella Toimii', 'nl' => 'RTP Uitgelegd: Hoe Return to Player Echt Werkt', 'ja' => 'RTP解説：プレイヤーへの還元率が実際にどう機能するか', 'pl' => 'RTP Wyjaśnione: Jak Naprawdę Działa Zwrot dla Gracza', 'cs' => 'RTP Vysvětleno: Jak Skutečně Funguje Návratnost pro Hráče', 'ro' => 'RTP Explicat: Cum Funcționează de Fapt Returnarea către Jucător', 'el' => 'Το RTP Εξηγημένο: Πώς Λειτουργεί Πραγματικά η Επιστροφή στον Παίκτη' ),
		'body'  => array(
			'en' => "What an RTP number actually means, why it's a long-run statistical average, and why it's not a promise about any single session you play.",
